using UnityEditor;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace DJMaster.EditorTools
{
    // The scene is generated by SceneBuilder. If you press Play on a scene built by older code, the game
    // would start with missing pieces, so rebuild it first and then start Play.
    [InitializeOnLoad]
    static class SceneAutoRebuild
    {
        static SceneAutoRebuild() => EditorApplication.playModeStateChanged += OnPlayModeChanged;

        static void OnPlayModeChanged(PlayModeStateChange change)
        {
            if (change != PlayModeStateChange.ExitingEditMode || Application.isBatchMode) return;
            if (SceneManager.GetActiveScene().path != SceneBuilder.ScenePath) return;
            var game = Object.FindAnyObjectByType<GameDirector>(FindObjectsInactive.Include);
            if (game != null && game.builtFrom == SceneBuilder.SourceHash()) return;

            EditorApplication.isPlaying = false;
            Debug.Log("[DJMaster] The scene was built by older code. Rebuilding it, then starting Play.");
            EditorApplication.delayCall += () =>
            {
                SceneBuilder.Build();
                EditorApplication.isPlaying = true;
            };
        }
    }
}
